import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"47、【困】 坎下兑上","description":"横渠易说 - 47、【困】 坎下兑上","frontmatter":{"title":"47、【困】 坎下兑上","description":"横渠易说 - 47、【困】 坎下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/049.md","filePath":"zh/classics/hengqu/049.md"}'),l={name:"zh/classics/hengqu/049.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_47、【困】-坎下兑上" tabindex="-1">47、【困】 坎下兑上 <a class="header-anchor" href="#_47、【困】-坎下兑上" aria-label="Permalink to “47、【困】 坎下兑上”">​</a></h1><h3 id="彖曰-困-刚掩也。险以说-困而不失其所亨-其唯君子乎-贞大人吉-以刚中也-有言不信-尚口乃穷也。" tabindex="-1">彖曰：困，刚掩也。险以说，困而不失其所亨，其唯君子乎!“贞大人吉”，以刚中也；“有言不信”，尚口乃穷也。 <a class="header-anchor" href="#彖曰-困-刚掩也。险以说-困而不失其所亨-其唯君子乎-贞大人吉-以刚中也-有言不信-尚口乃穷也。" aria-label="Permalink to “彖曰：困，刚掩也。险以说，困而不失其所亨，其唯君子乎!“贞大人吉”，以刚中也；“有言不信”，尚口乃穷也。”">​</a></h3><h3 id="象曰-泽无水-困-君子以致命遂志。" tabindex="-1">象曰：泽无水，困，君子以致命遂志。 <a class="header-anchor" href="#象曰-泽无水-困-君子以致命遂志。" aria-label="Permalink to “象曰：泽无水，困，君子以致命遂志。”">​</a></h3><p>升而不己必困，故受之以困。困于险下，柔不自振，非穷而能亨，致命遂志者也。</p><h3 id="初六-臀困于株木-入于幽谷-三岁不觌。-象曰-入于幽谷-幽不明也。" tabindex="-1">初六，臀困于株木，入于幽谷，三岁不觌。 象曰：“入于幽谷”，幽不明也。 <a class="header-anchor" href="#初六-臀困于株木-入于幽谷-三岁不觌。-象曰-入于幽谷-幽不明也。" aria-label="Permalink to “初六，臀困于株木，入于幽谷，三岁不觌。 象曰：“入于幽谷”，幽不明也。”">​</a></h3><p>处困者正乃无咎，居非得中，故幽而不明。</p><h3 id="九二-困于酒食-朱绂方来-利用享祀-征凶-无咎。-象曰-困于酒食-中有庆也。" tabindex="-1">九二，困于酒食，朱绂方来，利用享祀，征凶，无咎。 象曰：“困于酒食”，中有庆也。 <a class="header-anchor" href="#九二-困于酒食-朱绂方来-利用享祀-征凶-无咎。-象曰-困于酒食-中有庆也。" aria-label="Permalink to “九二，困于酒食，朱绂方来，利用享祀，征凶，无咎。 象曰：“困于酒食”，中有庆也。”">​</a></h3><p>困危之际，物思所附。九二以刚居中正，大人之吉，上下交说，不施聪明，美物方至，然未可有为，故以祭则吉，以征则凶，征虽或凶，于义无咎。际一作世。</p><h3 id="六三-困于石-据于蒺藜-入于其宫不见其妻-凶。-象曰-据于蒺藜-乘刚也-入于其宫不见其妻-不祥也。" tabindex="-1">六三，困于石，据于蒺藜，入于其宫不见其妻，凶。 象曰：“据于蒺藜”，乘刚也；“入于其宫不见其妻”，不祥也。 <a class="header-anchor" href="#六三-困于石-据于蒺藜-入于其宫不见其妻-凶。-象曰-据于蒺藜-乘刚也-入于其宫不见其妻-不祥也。" aria-label="Permalink to “六三，困于石，据于蒺藜，入于其宫不见其妻，凶。 象曰：“据于蒺藜”，乘刚也；“入于其宫不见其妻”，不祥也。”">​</a></h3><h3 id="九四-来徐徐-困于金车-吝有终。-象曰-来徐徐-志在下也-虽不当位-有与也。" tabindex="-1">九四，来徐徐，困于金车，吝有终。 象曰：“来徐徐”，志在下也，虽不当位，有与也。 <a class="header-anchor" href="#九四-来徐徐-困于金车-吝有终。-象曰-来徐徐-志在下也-虽不当位-有与也。" aria-label="Permalink to “九四，来徐徐，困于金车，吝有终。 象曰：“来徐徐”，志在下也，虽不当位，有与也。”">​</a></h3><p>心有偏系，吝也，以阳履柔，故有终。</p><h3 id="九五-劓刖-困于赤绂-乃徐有说-利用祭祀。-象曰-劓刖-志未得也-乃徐有说-以中直也-利用祭祀-受福也。" tabindex="-1">九五，劓刖，困于赤绂，乃徐有说，利用祭祀。 象曰：“劓刖”，志未得也；“乃徐有说”，以中直也；“利用祭祀”，受福也。 <a class="header-anchor" href="#九五-劓刖-困于赤绂-乃徐有说-利用祭祀。-象曰-劓刖-志未得也-乃徐有说-以中直也-利用祭祀-受福也。" aria-label="Permalink to “九五，劓刖，困于赤绂，乃徐有说，利用祭祀。 象曰：“劓刖”，志未得也；“乃徐有说”，以中直也；“利用祭祀”，受福也。”">​</a></h3><p>以阳居阳，处困以刚，威怒以求物之来，是反为赤绂所困者也，与九二之义反矣。苟能徐以俟之，乃心有说，故曰“乃徐有说”。物既自至，以事鬼神，然后福可致焉。处困用中，可以不失其守而已，故言“利用祭祀”，然非有为之时也。</p><h3 id="上六-困于葛藟-于臲卼-曰动悔有悔-征吉。-象曰-困于葛藟-未当也-动悔有悔-吉行也。" tabindex="-1">上六，困于葛藟，于臲卼，曰动悔有悔，征吉。 象曰：“困于葛藟”，未当也；“动悔有悔”，吉行也。 <a class="header-anchor" href="#上六-困于葛藟-于臲卼-曰动悔有悔-征吉。-象曰-困于葛藟-未当也-动悔有悔-吉行也。" aria-label="Permalink to “上六，困于葛藟，于臲卼，曰动悔有悔，征吉。 象曰：“困于葛藟”，未当也；“动悔有悔”，吉行也。”">​</a></h3><p>处困之极，重刚在下，不得其肆，居非所安，举则招悔，取舍皆咎，故行然后吉。一云：“动悔有悔”，犹云动悔之悔也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
